protected void addPathFile(File pathComponent) throws IOException {
    if (!pathComponents.contains(pathComponent)) {
        pathComponents.addElement(pathComponent);
    }
    if (pathComponent.isDirectory()) {
        return;
    }

    String manifestClasspath = getManifestClasspath(pathComponent);
    if (manifestClasspath == null || manifestClasspath.isEmpty()) {
        return;
    }

    URL baseURL = FILE_UTILS.getFileURL(pathComponent);
    StringTokenizer st = new StringTokenizer(manifestClasspath);
    while (st.hasMoreTokens()) {
        String classpathElement = st.nextToken();
        URL libraryURL = new URL(baseURL, classpathElement);
        if (!libraryURL.getProtocol().equals("file")) {
            log("Skipping jar library " + classpathElement
                    + " since only relative URLs are supported by this" + " loader",
                    Project.MSG_VERBOSE);
            continue;
        }
        String decodedPath = Locator.decodeUri(libraryURL.getFile());
        File libraryFile = new File(decodedPath);
        if (libraryFile.exists() && !isInPath(libraryFile)) {
            addPathFile(libraryFile);
        }
    }
}

/**
 * Retrieves the Class-Path attribute from the manifest of the given JAR file.
 * Caches the result based on file path, last modified time, and size.
 *
 * @param pathComponent the JAR file to inspect
 * @return the manifest's Class-Path value, or null if not present
 * @throws IOException if the manifest cannot be read
 */
private String getManifestClasspath(File pathComponent) throws IOException {
    String cacheKey = pathComponent.getAbsolutePath()
            + pathComponent.lastModified() + "-" + pathComponent.length();
    String cached = pathMap.get(cacheKey);
    if (cached != null) {
        return cached;
    }

    JarFile jarFile = null;
    try {
        jarFile = new JarFile(pathComponent);
        Manifest manifest = jarFile.getManifest();
        if (manifest == null) {
            return null;
        }
        String classpath = manifest.getMainAttributes()
                .getValue(Attributes.Name.CLASS_PATH);
        pathMap.put(cacheKey, classpath == null ? "" : classpath);
        return classpath;
    } finally {
        if (jarFile != null) {
            jarFile.close();
        }
    }
}

 * Dissect the specified absolute path.
 * @param path the path to dissect.
 * @return String[] {root, remaining path}.
 * @throws java.lang.NullPointerException if path is null.
 * @since Ant 1.7
 */
public String[] dissect(String path) {
    char sep = File.separatorChar;
    path = path.replace('/', sep).replace('\\', sep);

    // make sure we are dealing with an absolute path
    if (!isAbsolutePath(path)) {
        throw new BuildException(path + " is not an absolute path");
    }
    String root = getRoot(path, sep);
    String remaining = extractRemainingPath(path, sep, root);
    return new String[] {root, remaining};
}

/**
 * Extracts the root portion of an absolute path.
 * Encapsulates logic for determining the filesystem root based on platform-specific formats.
 * @param path the normalized absolute path.
 * @param sep the platform-specific file separator.
 * @return the root portion of the path (e.g., "C:\", "\\server\share\", or "/").
 */
private String getRoot(String path, char sep) {
    int colon = path.indexOf(':');
    if (colon > 0 && (ON_DOS || ON_NETWARE)) {
        return extractDosNetwareRoot(path, colon, sep);
    } else if (path.length() > 1 && path.charAt(1) == sep) {
        return extractUncRoot(path, sep);
    } else {
        return String.valueOf(sep);
    }
}

/**
 * Extracts the remaining path component after the root.
 * Handles platform-specific normalization like removing duplicate separators.
 * @param path the normalized absolute path.
 * @param sep the platform-specific file separator.
 * @param root the precomputed root portion.
 * @return the remaining path after the root, normalized.
 */
private String extractRemainingPath(String path, char sep, String root) {
    if (root.length() == 2 && root.charAt(1) == ':') { // DOS/Netware drive letter root
        int next = root.length();
        if (path.length() > next && path.charAt(next) == sep) {
            next++;
        }
        return removeConsecutiveSlashes(path.substring(next), sep);
    } else if (root.length() > 2) { // UNC root
        return path.substring(root.length());
    } else { // Unix-style root "/"
        return path.substring(1);
    }
}

/**
 * Removes consecutive duplicate file separators from the given path segment.
 * @param segment the path segment to normalize.
 * @param sep the file separator character.
 * @return the normalized path segment with no consecutive separators.
 */
private String removeConsecutiveSlashes(String segment, char sep) {
    StringBuilder sb = new StringBuilder(segment.length());
    char prev = 0;
    for (int i = 0; i < segment.length(); i++) {
        char c = segment.charAt(i);
        if (c != sep || prev != sep) {
            sb.append(c);
            prev = c;
        }
    }
    return sb.toString();
}

/**
 * Builds the root string for DOS/NetWare-style paths (e.g., "C:\").
 * @param path the full path string.
 * @param colonIndex the index of the colon in the drive specifier.
 * @param sep the file separator character.
 * @return the drive root, including the separator.
 */
private String extractDosNetwareRoot(String path, int colonIndex, char sep) {
    String root = path.substring(0, colonIndex + 1) + sep;
    // Remove leading separator after drive spec
    int next = colonIndex + 1;
    if (next < path.length() && path.charAt(next) == sep) {
        next++;
    }
    return root + removeConsecutiveSlashes(path.substring(next), sep);
}

/**
 * Extracts UNC root from a path, e.g., "\\server\share".
 * @param path the full normalized path.
 * @param sep the file separator character.
 * @return the UNC root if present, else full path if malformed.
 */
private String extractUncRoot(String path, char sep) {
    int nextsep = path.indexOf(sep, 2);
    nextsep = path.indexOf(sep, nextsep + 1);
    if (nextsep > 2) {
        return path.substring(0, nextsep + 1);
    }
    return path;
}

