private String getAltCompilerName(String anImplementation) {
    if (isModernVariant(anImplementation)) {
        return MODERN;
    }
    if (isClassicVariant(anImplementation)) {
        return CLASSIC;
    }
    if (MODERN.equalsIgnoreCase(anImplementation)) {
        return getModernFallback();
    }
    if (CLASSIC.equalsIgnoreCase(anImplementation)) {
        return assumedJavaVersion();
    }
    if (EXTJAVAC.equalsIgnoreCase(anImplementation)) {
        return assumedJavaVersion();
    }
    return null;
}

private boolean isModernVariant(String impl) {
    return JAVAC17.equalsIgnoreCase(impl)
        || JAVAC18.equalsIgnoreCase(impl)
        || JAVAC16.equalsIgnoreCase(impl)
        || JAVAC15.equalsIgnoreCase(impl)
        || JAVAC14.equalsIgnoreCase(impl)
        || JAVAC13.equalsIgnoreCase(impl);
}

private boolean isClassicVariant(String impl) {
    return JAVAC12.equalsIgnoreCase(impl)
        || JAVAC11.equalsIgnoreCase(impl);
}

private String getModernFallback() {
    String next = assumedJavaVersion();
    if (isModernVariant(next)) {
        return next;
    }
    return null;
}

