    private void addToPopup(ActionList popUpActions, List<Action> actions) {
        for (Action a : actions) {
            if (a instanceof List) {
                JMenu m = new JMenu((Action) a);
                popUpActions.add(m);
                for (Action subAction : (List<Action>) a) {
                    m.add(subAction);
                }
            } else {
                popUpActions.add(a);
            }
        }
