/**
 * Adds classifier roles from a given AssociationEnd to the provided list.
 * Assumes the end is part of an AssociationEndRole.
 *
 * @param end    the association end to process
 * @param role   the original classifier role
 * @param roles  the list to populate with related classifier roles
 */
private void addClassifierRolesFromEnd(AssociationEnd end, ClassifierRole role,
                                       List<Classifier> roles) {
    if (!(end instanceof AssociationEndRole)) {
        return;
    }
    UmlAssociation assoc = end.getAssociation();
    for (AssociationEnd end2 : assoc.getConnection()) {
        Classifier potentialRole = end2.getParticipant();
        if (potentialRole != role
                && potentialRole instanceof ClassifierRole) {
            roles.add(potentialRole);
        }
    }
}

