    public Object findOperationByName(Object trans, String opname) {
        if (!(trans instanceof Transition)) {
            throw new IllegalArgumentException();
        }

        try {
            Object sm = getStateMachine(trans);
            Object context = Model.getFacade().getContext(sm);
            Classifier classifier = findClassifier(context);
            Feature found = findInClassifier(classifier, opname);
            if (found != null) {
                return found;
            }

            Namespace pack = findSearchNamespace(context, classifier);
            return findInPackage(pack, opname);
        } catch (InvalidObjectException e) {
            throw new InvalidElementException(e);
        }
    }

    /**
     * Extracts a Classifier from the given context.
     * @param context The context object (may be Classifier or BehavioralFeature)
     * @return The Classifier, or null if none found
     */
    private Classifier findClassifier(Object context) {
        if (context instanceof Classifier) {
            return (Classifier) context;
        }
        if (context instanceof BehavioralFeature) {
            return ((BehavioralFeature) context).getOwner();
        }
        return null;
    }

    /**
     * Searches for an Operation with the given name in the provided Classifier.
     * @param classifier The Classifier to search
     * @param opname The operation name to match
     * @return The matching Feature (Operation), or null if not found
     */
    private Feature findInClassifier(Classifier classifier, String opname) {
        if (classifier == null) {
            return null;
        }
        List<Feature> features = classifier.getFeature();
        for (Feature f : features) {
            if (f instanceof Operation && opname.equals(f.getName())) {
                return f;
            }
        }
        return null;
    }

    /**
     * Determines the Namespace to search for operations based on context.
     * @param context The context object
     * @param classifier The classifier (may be null)
     * @return The Namespace to search, or null if none found
     */
    private Namespace findSearchNamespace(Object context, Classifier classifier) {
        if (context instanceof UmlPackage) {
            return (Namespace) context;
        }
        if (classifier != null) {
            Namespace parent = classifier.getNamespace();
            while (parent instanceof Classifier) {
                Namespace next = parent.getNamespace();
                if (next == null) {
                    break;
                }
                parent = next;
            }
            return parent;
        }
        return null;
    }

    /**
     * Searches for an Operation with the given name within owned Classifiers of the Namespace.
     * @param pack The Namespace to search
     * @param opname The operation name to match
     * @return The matching Feature (Operation), or null if not found
     */
    private Feature findInPackage(Namespace pack, String opname) {
        if (pack == null) {
            return null;
        }
        Collection<ModelElement> mes = pack.getOwnedElement();
        for (ModelElement me : mes) {
            if (me instanceof Classifier) {
                Classifier classifier2 = (Classifier) me;
                Feature found = findInClassifier(classifier2, opname);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

