private boolean shouldReturnEarlyFromLocatedBlocksFetch(LocatedBlocks newInfo) {
    return newInfo == null;
  }

  private boolean blocksHaveChanged(LocatedBlocks oldInfo, LocatedBlocks newInfo) {
    if (oldInfo == null || newInfo == null) {
      return false;
    }
    Iterator<LocatedBlock> oldIter = oldInfo.getLocatedBlocks().iterator();
    Iterator<LocatedBlock> newIter = newInfo.getLocatedBlocks().iterator();
    while (oldIter.hasNext() && newIter.hasNext()) {
      if (!oldIter.next().getBlock().equals(newIter.next().getBlock())) {
        return true;
      }
    }
    return false;
  }

  private boolean shouldReturnZeroAfterCheckingEmptyBlock(LocatedBlock last, long lastBlockBeingWrittenLength) {
    return last.getBlockSize() == 0;
  }

  private boolean shouldReturnNegativeOneAfterCheckingEmptyLocations(LocatedBlock last) {
    return last.getLocations().length == 0;
  }

  private boolean shouldUpdateLastBlockBeingWrittenLength(LocatedBlock last) {
    return last != null;
  }

  private long readBlockLengthSafely(LocatedBlock locatedblock) throws IOException {
    assert locatedblock != null : "LocatedBlock cannot be null";
    int replicaNotFoundCount = locatedblock.getLocations().length;

    for (DatanodeInfo datanode : locatedblock.getLocations()) {
      ClientDatanodeProtocol cdp = null;
      try {
        cdp = DFSUtil.createClientDatanodeProtocolProxy(datanode,
            dfsClient.getConfiguration(), dfsClient.getConf().socketTimeout,
            dfsClient.getConf().connectToDnViaHostname, locatedblock);
        final long n = cdp.getReplicaVisibleLength(locatedblock.getBlock());
        if (n >= 0) {
          return n;
        }
      } catch (IOException ioe) {
        if (ioe instanceof RemoteException &&
            (((RemoteException) ioe).unwrapRemoteException() instanceof
                ReplicaNotFoundException)) {
          replicaNotFoundCount--;
        }
        if (DFSClient.LOG.isDebugEnabled()) {
          DFSClient.LOG.debug("Failed to getReplicaVisibleLength from datanode "
              + datanode + " for block " + locatedblock.getBlock(), ioe);
        }
      } finally {
        if (cdp != null) {
          RPC.stopProxy(cdp);
        }
      }
    }

    if (replicaNotFoundCount == 0) {
      return 0;
    }

    throw new IOException("Cannot obtain block length for " + locatedblock);
  }

  private boolean shouldProcessLastBlockUnsafely(LocatedBlocks newInfo) {
    return !newInfo.isLastBlockComplete();
  }

  private void updateLocatedBlocksIfChanged(LocatedBlocks newInfo) throws IOException {
    if (blocksHaveChanged(locatedBlocks, newInfo)) {
      throw new IOException("Blocklist for " + src + " has changed!");
    }
    locatedBlocks = newInfo;
  }

  private void handleIncompleteLastBlock(LocatedBlocks newInfo) throws IOException {
    final LocatedBlock last = newInfo.getLastLocatedBlock();
    if (shouldUpdateLastBlockBeingWrittenLength(last)) {
      if (shouldReturnZeroAfterCheckingEmptyBlock(last, lastBlockBeingWrittenLength)) {
        lastBlockBeingWrittenLength = 0;
      } else if (shouldReturnNegativeOneAfterCheckingEmptyLocations(last)) {
        lastBlockBeingWrittenLength = -1;
      } else {
        final long len = readBlockLengthSafely(last);
        last.getBlock().setNumBytes(len);
        lastBlockBeingWrittenLength = len;
      }
    }
  }

  private void updateEncryptionInfo(LocatedBlocks newInfo) {
    fileEncryptionInfo = newInfo.getFileEncryptionInfo();
  }

  private void logNewInfoIfDebugging(LocatedBlocks newInfo) {
    if (DFSClient.LOG.isDebugEnabled()) {
      DFSClient.LOG.debug("newInfo = " + newInfo);
    }
  }

  private long fetchLocatedBlocksAndGetLastBlockLength() throws IOException {
    final LocatedBlocks newInfo = dfsClient.getLocatedBlocks(src, 0);
    logNewInfoIfDebugging(newInfo);

    if (shouldReturnEarlyFromLocatedBlocksFetch(newInfo)) {
      throw new IOException("Cannot open filename " + src);
    }

    if (locatedBlocks != null) {
      updateLocatedBlocksIfChanged(newInfo);
    }

    locatedBlocks = newInfo;
    lastBlockBeingWrittenLength = 0;

    if (shouldProcessLastBlockUnsafely(newInfo)) {
      handleIncompleteLastBlock(newInfo);
    }

    updateEncryptionInfo(newInfo);

    return lastBlockBeingWrittenLength;
  }

private synchronized void setupConnection() throws IOException {
  short ioFailures = 0;
  short timeoutFailures = 0;
  while (true) {
    try {
      establishSocketConnection();
      configureSocketTimeouts();
      return;
    } catch (ConnectTimeoutException toe) {
      handleTimeoutFailure(toe, timeoutFailures++, maxRetriesOnSocketTimeouts);
    } catch (IOException ie) {
      handleIoFailure(ie, ioFailures++);
    }
  }
}

private void establishSocketConnection() throws IOException {
  this.socket = socketFactory.createSocket();
  this.socket.setTcpNoDelay(tcpNoDelay);
  this.socket.setKeepAlive(true);

  bindSocketToPrincipalAddress();

  NetUtils.connect(this.socket, server, connectionTimeout);
}

private void bindSocketToPrincipalAddress() throws IOException {
  UserGroupInformation ticket = remoteId.getTicket();
  if (ticket == null || !ticket.hasKerberosCredentials()) {
    return;
  }

  KerberosInfo krbInfo = remoteId.getProtocol().getAnnotation(KerberosInfo.class);
  if (krbInfo == null || krbInfo.clientPrincipal() == null) {
    return;
  }

  String host = SecurityUtil.getHostFromPrincipal(remoteId.getTicket().getUserName());
  InetAddress localAddr = NetUtils.getLocalInetAddress(host);
  if (localAddr != null) {
    this.socket.bind(new InetSocketAddress(localAddr, 0));
  }
}

private void configureSocketTimeouts() {
  if (rpcTimeout > 0) {
    pingInterval = rpcTimeout;  // rpcTimeout overwrites pingInterval
  }
  this.socket.setSoTimeout(pingInterval);
}

private void handleTimeoutFailure(ConnectTimeoutException toe, short currentRetries, int maxRetries) throws IOException {
  if (updateAddress()) {
    timeoutFailures = ioFailures = 0;
  }
  handleConnectionTimeout(currentRetries, maxRetries, toe);
}

private void handleIoFailure(IOException ie, short currentRetries) throws IOException {
  if (updateAddress()) {
    timeoutFailures = ioFailures = 0;
  }
  handleConnectionFailure(currentRetries, ie);
}

private synchronized void setupConnection() throws IOException {
  short ioFailures = 0;
  short timeoutFailures = 0;
  while (true) {
    try {
      establishSocketConnection();
      configureSocketTimeouts();
      return;
    } catch (ConnectTimeoutException toe) {
      handleTimeoutFailure(toe, timeoutFailures++, maxRetriesOnSocketTimeouts);
    } catch (IOException ie) {
      handleIoFailure(ie, ioFailures++);
    }
  }
}

private void establishSocketConnection() throws IOException {
  this.socket = socketFactory.createSocket();
  this.socket.setTcpNoDelay(tcpNoDelay);
  this.socket.setKeepAlive(true);

  bindSocketToPrincipalAddress();

  NetUtils.connect(this.socket, server, connectionTimeout);
}

private void bindSocketToPrincipalAddress() throws IOException {
  UserGroupInformation ticket = remoteId.getTicket();
  if (ticket == null || !ticket.hasKerberosCredentials()) {
    return;
  }

  KerberosInfo krbInfo = remoteId.getProtocol().getAnnotation(KerberosInfo.class);
  if (krbInfo == null || krbInfo.clientPrincipal() == null) {
    return;
  }

  String host = SecurityUtil.getHostFromPrincipal(remoteId.getTicket().getUserName());
  InetAddress localAddr = NetUtils.getLocalInetAddress(host);
  if (localAddr != null) {
    this.socket.bind(new InetSocketAddress(localAddr, 0));
  }
}

private void configureSocketTimeouts() {
  if (rpcTimeout > 0) {
    pingInterval = rpcTimeout;  // rpcTimeout overwrites pingInterval
  }
  this.socket.setSoTimeout(pingInterval);
}

private void handleTimeoutFailure(ConnectTimeoutException toe, short currentRetries, int maxRetries) throws IOException {
  if (updateAddress()) {
    timeoutFailures = ioFailures = 0;
  }
  handleConnectionTimeout(currentRetries, maxRetries, toe);
}

private void handleIoFailure(IOException ie, short currentRetries) throws IOException {
  if (updateAddress()) {
    timeoutFailures = ioFailures = 0;
  }
  handleConnectionFailure(currentRetries, ie);
}

"""Default tags used by the template system, available to all templates."""
from __future__ import unicode_literals

import re
import sys
import warnings
from collections import namedtuple
from datetime import datetime
