  }
  return node;
}

/**
 * Attempts to locate a datanode descriptor using fallback logic:
 * 1. Look for a machine-local node in the resolved rack.
 * 2. If not found, choose a random node from the resolved rack.
 * 3. If still not found, choose any random node in the cluster.
 *
 * @param dnId DatanodeID parsed from the input address
 * @return DatanodeDescriptor fallback match, never null
 */
private DatanodeDescriptor getFallbackDatanodeDescriptor(DatanodeID dnId) {
  String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);
  List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);

  // Try machine-local node within the resolved rack.
  DatanodeDescriptor result = findMachineLocalDatanode(rackNodes, dnId.getIpAddr());
  if (result != null) {
    return result;
  }

  // Try rack-local node: random node in the resolved rack.
  result = getRandomDatanodeFromRack(rackNodes);
  if (result != null) {
    return result;
  }

  // Fallback to any node in the cluster.
  return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
}

/**
 * Finds a machine-local DatanodeDescriptor from the given rack nodes.
 *
 * @param rackNodes list of nodes in the resolved rack
 * @param targetIp  IP address the client is looking for
 * @return DatanodeDescriptor matching targetIp, or null if none found
 */
private DatanodeDescriptor findMachineLocalDatanode(List<Node> rackNodes, String targetIp) {
  if (rackNodes == null) {
    return null;
  }
  for (Node rackNode : rackNodes) {
    DatanodeDescriptor descriptor = (DatanodeDescriptor) rackNode;
    if (descriptor.getIpAddr().equals(targetIp)) {
      return descriptor;
    }
  }
  return null;
}

/**
 * Returns a random DatanodeDescriptor from the given rack node list,
 * or null if the list is empty.
 *
 * @param rackNodes list of nodes in the resolved rack
 * @return random DatanodeDescriptor from the rack, or null if list is empty
 */
private DatanodeDescriptor getRandomDatanodeFromRack(List<Node> rackNodes) {
  if (rackNodes == null || rackNodes.isEmpty()) {
    return null;
  }
  return (DatanodeDescriptor) rackNodes.get(DFSUtil.getRandom().nextInt(rackNodes.size()));
}

