class Dumper implements Runnable {
    /** Dump data into a file */
    private void dump() {
      // Create dump outputstream for the first time
      if (dumpOut == null) {
        dumpOut = createDumpOutputStream();
        if (dumpOut == null) {
          return;
        }
      }

      // Get raf for the first dump
      if (raf == null) {
        raf = createRandomAccessFile();
        if (raf == null) {
          return;
        }
      }

      if (LOG.isDebugEnabled()) {
        LOG.debug("Start dump. Before dump, nonSequentialWriteInMemory == "
            + nonSequentialWriteInMemory.get());
      }

      dumpPendingWrites();

      if (LOG.isDebugEnabled()) {
        LOG.debug("After dump, nonSequentialWriteInMemory == "
            + nonSequentialWriteInMemory.get());
      }
    }

    private FileOutputStream createDumpOutputStream() {
      LOG.info("Create dump file: " + dumpFilePath);
      File dumpFile = new File(dumpFilePath);
      try {
        synchronized (this) {
          // check if alive again
          Preconditions.checkState(dumpFile.createNewFile(),
              "The dump file should not exist: %s", dumpFilePath);
          return new FileOutputStream(dumpFile);
        }
      } catch (IOException e) {
        LOG.error("Got failure when creating dump stream " + dumpFilePath, e);
        enabledDump = false;
        return null;
      }
    }

    private RandomAccessFile createRandomAccessFile() {
      try {
        return new RandomAccessFile(dumpFilePath, "r");
      } catch (FileNotFoundException e) {
        LOG.error("Can't get random access to file " + dumpFilePath);
        enabledDump = false;
        return null;
      }
    }

    private void dumpPendingWrites() {
      Iterator<OffsetRange> it = pendingWrites.keySet().iterator();
      while (activeState && it.hasNext()
          && nonSequentialWriteInMemory.get() > 0) {
        OffsetRange key = it.next();
        WriteCtx writeCtx = pendingWrites.get(key);
        if (writeCtx == null) {
          // This write was just deleted
          continue;
        }
        try {
          long dumpedDataSize = writeCtx.dumpData(dumpOut, raf);
          if (dumpedDataSize > 0) {
            updateNonSequentialWriteInMemory(-dumpedDataSize);
          }
        } catch (IOException e) {
          LOG.error("Dump data failed: " + writeCtx + " with error: " + e
              + " OpenFileCtx state: " + activeState);
          enabledDump = false;
          return;
        }
      }
    }

 public RemoteIterator<LocatedFileStatus> listFiles(
    final Path f, final boolean recursive) throws AccessControlException,
    FileNotFoundException, UnsupportedFileSystemException, 
    IOException {
  return new RemoteIterator<LocatedFileStatus>() {
    private Stack<RemoteIterator<LocatedFileStatus>> itors = 
      new Stack<RemoteIterator<LocatedFileStatus>>();
    RemoteIterator<LocatedFileStatus> curItor = listLocatedStatus(f);
    LocatedFileStatus curFile;

    /**
     * Returns <tt>true</tt> if the iterator has more files.
     *
     * @return <tt>true</tt> if the iterator has more files.
     * @throws AccessControlException if not allowed to access next
     *                                file's status or locations
     * @throws FileNotFoundException if next file does not exist any more
     * @throws UnsupportedFileSystemException if next file's 
     *                                        fs is unsupported
     * @throws IOException for all other IO errors
     *                     for example, NameNode is not avaialbe or
     *                     NameNode throws IOException due to an error
     *                     while getting the status or block locations
     */
    @Override
    public boolean hasNext() throws IOException {
      while (curFile == null) {
        if (curItor.hasNext()) {
          handleFileStat(curItor.next());
        } else if (!itors.empty()) {
          curItor = itors.pop();
        } else {
          return false;
        }
      }
      return true;
    }

    /**
     * Process the input stat.
     * If it is a file, return the file stat.
     * If it is a directory, traverse the directory if recursive is true;
     * ignore it if recursive is false.
     * If it is a symlink, resolve the symlink first and then process it
     * depending on if it is a file or directory.
     * @param stat input status
     * @throws AccessControlException if access is denied
     * @throws FileNotFoundException if file is not found
     * @throws UnsupportedFileSystemException if fs is not supported
     * @throws IOException for all other IO errors
     */
    private void handleFileStat(LocatedFileStatus stat)
    throws IOException {
      if (stat.isFile()) { // file
        curFile = stat;
      } else if (stat.isSymlink()) { // symbolic link
        FileStatus symstat = resolveSymlinkAndProcess(stat);
        if (shouldTraverse(symstat, recursive)) {
          itors.push(curItor);
          curItor = listLocatedStatus(stat.getPath());
        }
      } else if (recursive) { // directory
        itors.push(curItor);
        curItor = listLocatedStatus(stat.getPath());
      }
    }

    /**
     * Resolve symlink and return its FileStatus.
     * @param stat LocatedFileStatus of the symlink
     * @return FileStatus after resolving the symlink
     * @throws IOException
     */
    private FileStatus resolveSymlinkAndProcess(LocatedFileStatus stat)
        throws IOException {
      return FileContext.this.getFileStatus(stat.getSymlink());
    }

    /**
     * Determine if the given FileStatus should be traversed based on its
     * type and the recursive flag.
     * @param symstat resolved FileStatus
     * @param recursive whether to traverse subdirectories
     * @return true if traversal is required
     */
    private boolean shouldTraverse(FileStatus symstat, boolean recursive) {
      return (symstat.isFile() || (recursive && symstat.isDirectory()));
    }

    /**
     * Returns the next file's status with its block locations
     *
     * @throws AccessControlException if not allowed to access next
     *                                file's status or locations
     * @throws FileNotFoundException if next file does not exist any more
     * @throws UnsupportedFileSystemException if next file's 
     *                                        fs is unsupported
     * @throws IOException for all other IO errors
     *                     for example, NameNode is not avaialbe or
     *                     NameNode throws IOException due to an error
     *                     while getting the status or block locations
     */
    @Override
    public LocatedFileStatus next() throws IOException {
      if (hasNext()) {
        LocatedFileStatus result = curFile;
        curFile = null;
        return result;
      } 
      throw new java.util.NoSuchElementException("No more entry in " + f);
    }
  };
