    public void	setTypedVariable(
		String	name, Class type, Object value,	boolean	isFinal) 
		throws EvalError 
	{
		if (variables == null)
			variables =	new Hashtable();

		if (value == null)
			value = getDefaultTypedValue(type);

		if (variables.containsKey(name)) {
			Object existing = getVariableImpl(name, false);
			if (existing instanceof TypedVariable) {
				TypedVariable typedVar = (TypedVariable) existing;
				if (typedVar.getType() != type) {
					throw new EvalError("Typed variable: " + name +
						" was previously declared with type: " + typedVar.getType());
				}
				typedVar.setValue(value);
				return;
			}
		}

		variables.put(name, new TypedVariable(type, value, isFinal));
	}

	private Object getDefaultTypedValue(Class<?> type) throws EvalError {
		if (!type.isPrimitive()) return Primitive.NULL;

		if (type == Boolean.TYPE)		return new Primitive(Boolean.FALSE);
		if (type == Byte.TYPE)			return new Primitive((byte)0);
		if (type == Short.TYPE)			return new Primitive((short)0);
		if (type == Character.TYPE)		return new Primitive((char)0);
		if (type == Integer.TYPE)		return new Primitive((int)0);
		if (type == Long.TYPE)			return new Primitive(0L);
		if (type == Float.TYPE)			return new Primitive(0.0f);
		if (type == Double.TYPE)		return new Primitive(0.0d);

		throw new EvalError("Unknown primitive type: " + type.getName());
	}
