    /**
     * Paints the chart to the given graphics context, handling buffering and scaling.
     * 
     * @param g2  the graphics context.
     */
    private void paintChart(Graphics2D g2) {
        Rectangle2D available = calculateAvailableArea();
        double[] scalingFactors = calculateScaling(available);
        this.scaleX = scalingFactors[0];
        this.scaleY = scalingFactors[1];
        Rectangle2D chartArea = createChartArea(scalingFactors[2], scalingFactors[3]);

        if (this.useBuffer) {
            prepareAndDrawBuffer(g2, available, chartArea);
        } else {
            drawChartWithoutBuffer(g2, chartArea);
        }
    }

    /**
     * Calculates the available drawing area considering panel size and insets.
     * 
     * @return The available drawing rectangle.
     */
    private Rectangle2D calculateAvailableArea() {
        Dimension size = getSize();
        Insets insets = getInsets();
        return new Rectangle2D.Double(insets.left, insets.top,
                size.getWidth() - insets.left - insets.right,
                size.getHeight() - insets.top - insets.bottom);
    }

    /**
     * Calculates scaling factors for the chart based on available space.
     * 
     * @param available  The available area.
     * @return An array [scaleX, scaleY, drawWidth, drawHeight].
     */
    private double[] calculateScaling(Rectangle2D available) {
        double drawWidth = available.getWidth();
        double drawHeight = available.getHeight();
        double scaleX = 1.0;
        double scaleY = 1.0;

        if (drawWidth < this.minimumDrawWidth) {
            scaleX = drawWidth / this.minimumDrawWidth;
            drawWidth = this.minimumDrawWidth;
        } else if (drawWidth > this.maximumDrawWidth) {
            scaleX = drawWidth / this.maximumDrawWidth;
            drawWidth = this.maximumDrawWidth;
        }

        if (drawHeight < this.minimumDrawHeight) {
            scaleY = drawHeight / this.minimumDrawHeight;
            drawHeight = this.minimumDrawHeight;
        } else if (drawHeight > this.maximumDrawHeight) {
            scaleY = drawHeight / this.maximumDrawHeight;
            drawHeight = this.maximumDrawHeight;
        }

        return new double[]{scaleX, scaleY, drawWidth, drawHeight};
    }

    /**
     * Creates the chart drawing area (unscaled).
     * 
     * @param width  The width.
     * @param height  The height.
     * @return The chart area.
     */
    private Rectangle2D createChartArea(double width, double height) {
        return new Rectangle2D.Double(0.0, 0.0, width, height);
    }

    /**
     * Prepares and draws the chart using the off-screen buffer.
     * 
     * @param g2  The graphics context for the component.
     * @param available  The available area.
     * @param chartArea  The unscaled chart area.
     */
    private void prepareAndDrawBuffer(Graphics2D g2, Rectangle2D available, Rectangle2D chartArea) {
        prepareBuffer(available);
        redrawBuffer(chartArea);
        g2.drawImage(this.chartBuffer, getInsets().left, getInsets().top, this);
    }

    /**
     * Resizes the chart buffer if needed.
     * 
     * @param available  The available area.
     */
    private void prepareBuffer(Rectangle2D available) {
        if ((this.chartBuffer == null)
                || (this.chartBufferWidth != (int) available.getWidth())
                || (this.chartBufferHeight != (int) available.getHeight())) {
            this.chartBufferWidth = (int) available.getWidth();
            this.chartBufferHeight = (int) available.getHeight();
            GraphicsConfiguration gc = getGraphicsConfiguration();
            this.chartBuffer = gc.createCompatibleImage(
                    this.chartBufferWidth, this.chartBufferHeight,
                    Transparency.TRANSLUCENT);
            this.refreshBuffer = true;
        }
    }

    /**
     * Redraws the buffer if needed.
     * 
     * @param chartArea  The chart area.
     */
    private void redrawBuffer(Rectangle2D chartArea) {
        if (this.refreshBuffer) {
            this.refreshBuffer = false;
            clearAndDrawBuffer(chartArea);
        }
    }

    /**
     * Clears the buffer and draws the chart within it.
     * 
     * @param chartArea  The chart area.
     */
    private void clearAndDrawBuffer(Rectangle2D chartArea) {
        Graphics2D bufferG2 = (Graphics2D) this.chartBuffer.getGraphics();
        Composite savedComposite = bufferG2.getComposite();
        bufferG2.setComposite(AlphaComposite.getInstance(AlphaComposite.CLEAR, 0.0f));
        bufferG2.fill(new Rectangle(0, 0, this.chartBufferWidth, this.chartBufferHeight));
        bufferG2.setComposite(savedComposite);

        if (isScalingRequired()) {
            AffineTransform saved = bufferG2.getTransform();
            bufferG2.transform(AffineTransform.getScaleInstance(this.scaleX, this.scaleY));
            this.chart.draw(bufferG2, chartArea, this.anchor, this.info);
            bufferG2.setTransform(saved);
        } else {
            Rectangle2D bufferArea = new Rectangle2D.Double(0, 0,
                    this.chartBufferWidth, this.chartBufferHeight);
            this.chart.draw(bufferG2, bufferArea, this.anchor, this.info);
        }
    }

    /**
     * Checks whether scaling is required.
     * 
     * @return true if scaling is required.
     */
    private boolean isScalingRequired() {
        return this.scaleX != 1.0 || this.scaleY != 1.0;
    }

    /**
     * Draws the chart directly without using a buffer.
     * 
     * @param g2  The graphics context.
     * @param chartArea  The chart area.
     */
    private void drawChartWithoutBuffer(Graphics2D g2, Rectangle2D chartArea) {
        Insets insets = getInsets();
        AffineTransform saved = g2.getTransform();
        g2.translate(insets.left, insets.top);
        if (isScalingRequired()) {
            g2.transform(AffineTransform.getScaleInstance(this.scaleX, this.scaleY));
        }
        this.chart.draw(g2, chartArea, this.anchor, this.info);
        g2.setTransform(saved);
    }

    /**
     * Draws all registered overlays on the chart.
     * 
     * @param g2  The graphics context.
     */
    private void drawOverlays(Graphics2D g2) {
        for (Iterator iterator = this.overlays.iterator(); iterator.hasNext(); ) {
            Overlay overlay = (Overlay) iterator.next();
            overlay.paintOverlay(g2, this);
        }
    }

    /**
     * Clears internal state after painting is complete.
     */
    private void clearState() {
        this.anchor = null;
        this.verticalTraceLine = null;
        this.horizontalTraceLine = null;
    }
